  @protected
  void sse_encode_mihomo_error(MihomoError self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case MihomoError_InvalidUrl(field0: final field0):
        sse_encode_i_32(0, serializer);
        sse_encode_String(field0, serializer);
      case MihomoError_InvalidRegex(
        pattern: final pattern,
        message: final message,
      ):
        sse_encode_i_32(1, serializer);
        sse_encode_String(pattern, serializer);
        sse_encode_String(message, serializer);
      case MihomoError_Upstream(status: final status, body: final body):
        sse_encode_i_32(2, serializer);
        sse_encode_u_16(status, serializer);
        sse_encode_String(body, serializer);
      case MihomoError_Network(field0: final field0):
        sse_encode_i_32(3, serializer);
        sse_encode_String(field0, serializer);
      case MihomoError_InvalidJson(field0: final field0):
        sse_encode_i_32(4, serializer);
        sse_encode_String(field0, serializer);
      case MihomoError_Other(field0: final field0):
        sse_encode_i_32(5, serializer);
        sse_encode_String(field0, serializer);
    }
  }

